#!/bin/bash
THRESHOLD=80
df -h | awk -v threshold=$THRESHOLD '
$5 ~ /%/$ {
    usage=$(substr($5, 1, length($5)-1))
    if (usage > threshold) {
        print "Alerta: El disco "$6" está al "usage"%"
        # Enviar notificación (ajusta según tu sistema)
        # mail -s "Disco lleno" admin@example.com
    }
}'
